    ['dc3296c7-b2cb-4c14-9084-8d8d2283a460','Klantlogo FunForest'],
    ['e1c89a66-d7aa-4a1e-b782-dc4964d9357a','Klantlogo Albert Heijn'],
    ['https://dagpakketverhuur.nl/wp-content/uploads/2026/09/dcterra_logo-vierkant_11zon.webp','Klantlogo DC Terra']
  ];
  var track=root.querySelector('[data-dpv-logos]');
  if(track){
    var html='';
    for(var r=0;r<3;r++)logos.forEach(function(l){
      var src=l[0].indexOf('http')===0?l[0]:'https://dagpakketverhuur.nl/wp-content/uploads/2026/03/'+l[0]+'.png';
      html+='<img data-skip-lazy class="skip-lazy no-lazyload" src="'+src+'" alt="'+l[1]+'" loading="lazy">';
    });
    track.innerHTML=html;
  }

  /* Reviews-carrousel */
  var rt=root.querySelector('[data-dpv-rev-track]');
  if(rt){
    var items=[].slice.call(rt.querySelectorAll('.dpv-rev')),
        dots=[].slice.call(root.querySelectorAll('[data-dpv-dot]')),cur=1;
    var paint=function(){
      [(cur+2)%items.length,cur,(cur+1)%items.length].forEach(function(i,pos){
        items[i].dataset.active=pos===1?'true':'false';
        rt.appendChild(items[i]);
      });
      dots.forEach(function(d,i){d.dataset.active=i===cur?'true':'false';});
    };
    q('[data-dpv-rev]').forEach(function(b){
      b.addEventListener('click',function(){
        cur=b.dataset.dpvRev==='next'?(cur+1)%items.length:(cur+items.length-1)%items.length;
        paint();
      });
    });
    dots.forEach(function(d,i){
      d.addEventListener('click',function(){cur=i;paint();});
    });
    /* Swipen op mobiel */
    var x0=null;
    rt.addEventListener('touchstart',function(e){x0=e.touches[0].clientX;},{passive:true});
    rt.addEventListener('touchend',function(e){
      if(x0===null)return;
      var dx=e.changedTouches[0].clientX-x0; x0=null;
      if(Math.abs(dx)<40)return;
      cur=dx<0?(cur+1)%items.length:(cur+items.length-1)%items.length;
      paint();
    },{passive:true});
    paint();
  }

  /* Scroll-animaties */
  var wrap=root.querySelector('.dpv-home'),
      reveal=[].slice.call(root.querySelectorAll('[data-reveal]'));
  if(wrap&&reveal.length&&'IntersectionObserver' in window){
    wrap.classList.add('dpv-anim');
    var io=new IntersectionObserver(function(es){
      es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('is-in');io.unobserve(e.target);}});
    },{rootMargin:'0px 0px -12% 0px',threshold:.12});
    reveal.forEach(function(el){io.observe(el);});
    setTimeout(function(){reveal.forEach(function(el){el.classList.add('is-in');});},3000);
  }

  /* Populaire producten: dezelfde kaarten als op de categoriepagina */
  if(grid&&!grid.dataset.dpvInit){
    grid.dataset.dpvInit='1';
    fetch('/wp-json/dpvs/v1/popular?limit=10',{credentials:'same-origin'})
      .then(function(r){return r.ok?r.json():Promise.reject(r.status);})
      .then(function(d){
        if(!d||!d.html)throw 0;
        grid.innerHTML=d.html;
      })
      .catch(function(){
        var sec=root.querySelector('slot[name="prods"]');
        if(sec&&sec.closest('section'))sec.closest('section').style.display='none';
        grid.innerHTML='';
      });
  }
})();
